add_shortcode( 'greeting', 'perfectpixel_greeting_shortcode' );

function perfectpixel_greeting_text( $hour ) {
	if ( $hour >= 5 && $hour < 12 ) {
		return '{{greeting_morning}}';
	}
	return ( $hour >= 12 && $hour < 21 ) ? '{{greeting_evening}}' : '{{greeting_night}}';
}

function perfectpixel_greeting_shortcode() {
	static $script_done = false;
	// Server time as a fallback; the script below switches to the visitor's own clock.
	$html = '<span class="perfectpixel-greeting">' . esc_html( perfectpixel_greeting_text( (int) wp_date( 'G' ) ) ) . '</span>';
	if ( ! $script_done ) {
		$script_done = true;
		$texts       = wp_json_encode( array( 'm' => '{{greeting_morning}}', 'e' => '{{greeting_evening}}', 'n' => '{{greeting_night}}' ) );
		$html       .= '<script>( function ( t ) { var run = function () { var h = new Date().getHours(); var s = ( h >= 5 && h < 12 ) ? t.m : ( ( h >= 12 && h < 21 ) ? t.e : t.n ); document.querySelectorAll( ".perfectpixel-greeting" ).forEach( function ( el ) { el.textContent = s; } ); }; if ( document.readyState === "loading" ) { document.addEventListener( "DOMContentLoaded", run ); } else { run(); } } )( ' . $texts . ' );</script>';
	}
	return $html;
}
